INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('2. diena — saulaina diena Vitrupē',
'Otrā diena Vitrupē, un saule spīdēja no rīta līdz vakaram.\n\nPastaiga pa pludmali bija silta — vējš gan pūta, bet ne auksti, drīzāk sāļi un svaigi. Priežu ēnas slīdēja pāri smiltīm, jūra mirdzēja zili, un gar krastu stiepās gara, tukša smilšu josla. Suņi izskraidījās līdz nogurumam, apoša katru sanesto koku un pietupās pie vecā, jūras izskalotā stumbra.\n\nTāda diena, kādu rudens reti dod — gaiša, mierīga, pilna gaismas.\n\nTagad esam atpakaļ mājiņā pie kafijas tases, un suņi saldi guļ. Diena bija laba.\n\n⸻\n\nToinen päivä Vitrupessa, ja aurinko paistoi aamusta iltaan.\n\nKävely rannalla oli lämmin — tuuli kyllä puhalsi, mutta ei kylmästi, pikemminkin suolaisena ja raikkaana. Mäntyjen varjot liukuivat hiekan yli, meri välkkyi sinisenä, ja rantaa pitkin kulki pitkä, tyhjä hiekkakaistale. Koirat juoksivat itsensä väsyksiin, nuuskivat jokaisen rantaan ajautuneen puun ja pysähtyivät vanhan, meren huuhtoman rungon viereen.\n\nSellainen päivä, jollaista syksy harvoin antaa — kirkas, rauhallinen, täynnä valoa.\n\nNyt olemme takaisin mökillä kahvikupin ääressä, ja koirat nukkuvat makeasti. Päivä oli hyvä.',
'celojums',
'2026-10-18 14:30:00',
1);
